phrase_pairs(s,[U],[('Bonjour !','бо(н)жу́р!','Здравствуйте!',['bonjour'],['bonjour']),('Je m’appelle Lila.','жё мапэль лила́.','Меня зовут Лила.',['je-mappelle'],['je-mappelle']),('Au revoir !','о рёвуа́р!','До свидания!',['au-revoir'],['au-revoir'])],'Вы различили начало общения, представление и прощание.','Приветствие, собственное имя и прощание выполняют разные задачи в разговоре.')
choose(s,'reading',[U],['bonjour','je-mappelle','et-toi'],['et-toi'],'Какого ответа ожидают после этих реплик в данном контексте?',fr('Bonjour ! Je m’appelle Lila. Et toi ?','бо(н)жу́р! жё мапэль лила́. э туа́?'),['Назвать место встречи','Назвать своё имя','Сообщить погоду'],1,'В этом контексте собеседнику предлагают тоже назвать своё имя.','Ответный вопрос относится к только что названному имени; место и погода здесь не обсуждаются.')
grammar(fill(s,[U],['je-mappelle','comment-tu-tappelles'],[],'Восстановите знакомое представление «Меня зовут Лила».','Je ','жё',' Lila.','лила́',[fr('t’appelles','тапэ́ль'),fr('m’appelle','мапэ́ль')],1,'Je m’appelle Lila.','жё мапэль лила́.','Восстановлен показанный ранее образец сообщения о собственном имени.','Для знакомого начала о себе требуется форма из собственного представления, а не часть вопроса к собеседнику.'))
order(s,[U],['bonjour','je-mappelle'],[],'Соберите «Здравствуйте! Меня зовут Лила». Начните с приветствия, затем представьтесь.',[('Bonjour !','бо(н)жу́р'),('Je m’appelle','жё мапэ́ль'),('Lila.','лила́')],'Bonjour ! Je m’appelle Lila.','бо(н)жу́р! жё мапэль лила́.','Получилось приветствие и собственное представление.','Сначала поставьте приветствие, затем целое начало представления и имя.')
page(s,[('Знакомство без предварительного ответа',['Задания возвращают ранее изученные выражения. Перед выбором не даётся французская реплика, которую осталось бы только скопировать.','Нужно различать вопрос об имени, собственное представление и прощание.'],[]),('Ответный вопрос в контексте',['Смысл короткого ответного вопроса определяется предыдущей репликой. В разговоре об имени он возвращает вопрос об имени собеседнику.'],[]),('Имена и способы ответа',['Используются уже встречавшиеся имена и формы. Все ответы выполняются выбором или сборкой, свободный рассказ не требуется.'],[])])

s=start(2,'Понимайте просьбу об одной знакомой вещи и короткий обмен при её получении. Повторите мягкую формулировку просьбы.',['je-mappelle','je-voudrais','je-veux','jaime','livre','pain','pomme','cafe','voila','merci','sil-vous-plait','je-prends','un-article','une-article'])
intro(s,1,'Новой лексики и грамматики нет. Для выбора просьбы учитывайте указанную в условии формулировку, предмет и количество. Не подменяйте просьбу сообщением о предпочтении.',[])
